import { useCallback, useEffect, useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { isRetired, usePeople, type Grade } from '../people/people';
import { useGradeCodes } from '../grades/grades';
import { twoDecimals, useRates } from '../rates/rates';
import { CLAIM_STATUSES, personDueCents, statusCount, trimmedSum, useClaims, useLate, useSheetTotals, type ClaimStatus } from '../claims/claims';
import { useAliases } from '../aliases/aliases';
import { useSheetToday } from '../sheet/sheet';
import { useFloorCents } from '../settings/settings';
import { useFamily } from './consolidated';
import { Fig } from '../locale/Fig';
import { useCapCentsOf } from '../pools/pools';

type Figures = {
  /** Each person's names as names are compared (lower-cased): their name, then their aliases. */
  people: string[][];
  /** Each person's due-total that is not n/a, and everyone's overdue-total, untrimmed. */
  due: bigint[];
  overdue: bigint[];
  /** The sheet's grades, in order, and per grade the due-totals of the people on it. */
  codes: Grade[];
  grades: Record<Grade, bigint>;
  statuses: Record<ClaimStatus, number>;
};

// One sheet's figures: its people (retired ones included) with their names and aliases, each person's due-total and
// overdue-total as the sheet's own totals take them before trimming, per grade the due-totals of the people on it (retired ones left out) and per status
// how many claims have it, each figured from the same helpers. Renders nothing; it reports them up.
function SheetFigures({ sheet, report }: { sheet: string; report: (sheet: string, f: Figures) => void }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);
  const capOf = useCapCentsOf(sheet);
  const { data: aliases = [] } = useAliases(sheet);
  const { figures } = useSheetTotals(sheet);
  const codes = useGradeCodes(sheet);
  const names = people.map((p) => [
    p.name.toLowerCase(),
    ...aliases.filter((a) => a.person === p.id).map((a) => a.alias.toLowerCase()),
  ]);
  const current = people.filter((p) => !isRetired(p));
  const grades = Object.fromEntries(
    codes.map((g) => [
      g,
      current
        .filter((p) => p.grade === g)
        .reduce((sum, p) => sum + (personDueCents(claims, rates, p, today, floor, late, capOf(p), people) ?? 0n), 0n),
    ]),
  ) as Record<Grade, bigint>;
  const statuses = Object.fromEntries(CLAIM_STATUSES.map((s) => [s, statusCount(claims, s)])) as Record<ClaimStatus, number>;
  // Keyed by value so the report runs only when a figure changes.
  const key = JSON.stringify([
    names,
    figures.due.map(String),
    figures.overdue.map(String),
    codes,
    codes.map((g) => grades[g].toString()),
    CLAIM_STATUSES.map((s) => statuses[s]),
  ]);
  useEffect(
    () => report(sheet, { people: names, due: figures.due, overdue: figures.overdue, codes, grades, statuses }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [sheet, report, key],
  );
  return null;
}

// The consolidated figures over the sheet and all its descendants (see useFamily): the people, each counted once across
// the tree (people whose names or aliases match, as names are compared, are one person); the due-total and the
// overdue-total, every person's figure over the whole tree added up and trimmed once (see trimmedSum); and the
// per-grade due-totals and the per-status claim counts of each sheet, added up. A sheet with no children shows its own. While the screen shows the sheet as of a
// date, every sheet of the tree is read as it stood at the end of that date, with the date for its today.
// How many distinct people there are among them, each given by their names: those sharing a name, directly or through
// others, are one.
function distinctPeople(people: string[][]): number {
  const parent = people.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const owner = new Map<string, number>();
  people.forEach((names, i) =>
    names.forEach((n) => {
      const j = owner.get(n);
      if (j === undefined) owner.set(n, i);
      else parent[find(i)] = find(j);
    }),
  );
  return new Set(people.map((_, i) => find(i))).size;
}

function Consolidated({ sheet }: { sheet: string; user: string }) {
  const { data: family = [sheet] } = useFamily(sheet);
  const [figures, setFigures] = useState<Map<string, Figures>>(new Map());
  const report = useCallback(
    (s: string, f: Figures) => setFigures((prev) => new Map(prev).set(s, f)),
    [],
  );
  const shown = family.map((s) => figures.get(s)).filter((f): f is Figures => f !== undefined);
  const people = distinctPeople(shown.flatMap((f) => f.people));
  const due = trimmedSum(shown.flatMap((f) => f.due));
  const overdue = trimmedSum(shown.flatMap((f) => f.overdue));
  // This sheet's grades, then any other grade of the tree, each once.
  const own = useGradeCodes(sheet);
  const codes = [...new Set([...own, ...shown.flatMap((f) => f.codes)])];
  const gradeDue = (g: Grade) => shown.reduce((n, f) => n + (f.grades[g] ?? 0n), 0n);
  const statusClaims = (s: ClaimStatus) => shown.reduce((n, f) => n + f.statuses[s], 0);
  return (
    <p>
      {family.map((s) => (
        <SheetFigures key={s} sheet={s} report={report} />
      ))}
      Consolidated: people <strong data-testid="consolidated-people-count">{people}</strong>, due total{' '}
      <strong data-testid="consolidated-due-total"><Fig>{twoDecimals(due)}</Fig></strong>, overdue total{' '}
      <strong data-testid="consolidated-overdue-total"><Fig>{twoDecimals(overdue)}</Fig></strong>
      {codes.map((g) => (
        <span key={g}>
          , grade {g} due total{' '}
          <strong data-testid={`consolidated-grade-${g}-due-total`}><Fig>{twoDecimals(gradeDue(g))}</Fig></strong>
        </span>
      ))}
      {CLAIM_STATUSES.map((s) => (
        <span key={s}>
          , {s} claims <strong data-testid={`consolidated-status-${s}-count`}>{statusClaims(s)}</strong>
        </span>
      ))}
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: -9, Component: Consolidated });
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import type { Person } from '../people/people';
import { hundredths, twoDecimals } from '../rates/rates';
import { personCutCents, usePools, type Pool } from './pools';
import { Fig } from '../locale/Fig';

/** The sheet's cut total in hundredths: every person's cut total added up. */
function sheetCutCents(pools: Pool[]): bigint {
  let cents = 0n;
  for (const pool of pools) {
    for (const m of pool.members) {
      if (m.memberPool === null && m.cut !== '') cents += hundredths(m.cut);
    }
  }
  return cents;
}

function CutTotalHeader() {
  return <th>Cut total</th>;
}

function PersonCutTotal({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: pools = [] } = usePools(sheet);
  return <td data-testid="person-cut-total"><Fig>{twoDecimals(personCutCents(pools, person.id))}</Fig></td>;
}

function SheetCutTotal({ sheet }: { sheet: string; user: string }) {
  const { data: pools = [] } = usePools(sheet);
  return (
    <p>
      Cut total: <strong data-testid="rollup-cut-total"><Fig>{twoDecimals(sheetCutCents(pools))}</Fig></strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 9.8, Component: CutTotalHeader }),
  PersonColumns.fill({ order: 9.8, Component: PersonCutTotal }),
  SheetPanels.fill({ order: 20.1, Component: SheetCutTotal }),
];
import { useCallback, useEffect, useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople } from '../people/people';
import { counted, overdue, statusCount, useClaims, useLate } from '../claims/claims';
import { useUserRole } from '../roles/roles';
import { useFamily } from '../consolidated/consolidated';

type Counts = { pending: number; review: number; overdue: number };

// One sheet's dashboard counts: how many claims are PENDING, how many are in REVIEW, and how many of the claims that
// count (see counted) are overdue, by that sheet's own today and late rules. Renders nothing; it reports them up.
function SheetCounts({ sheet, report }: { sheet: string; report: (sheet: string, c: Counts) => void }) {
  const { data: claims = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const late = useLate(sheet);
  const pending = statusCount(claims, 'PENDING');
  const review = statusCount(claims, 'REVIEW');
  const overdueCount = counted(claims, people).filter((c) => overdue(c, late)).length;
  useEffect(() => report(sheet, { pending, review, overdue: overdueCount }), [sheet, report, pending, review, overdueCount]);
  return null;
}

// A steward's dashboard over the sheet and all its descendants (see useFamily): each sheet's counts (see SheetCounts),
// added up. A sheet with no children shows its own. A user not acting as a steward on the sheet sees the cells empty.
// Under an as-of date every read is the sheet as it stood then, so the counts and the role are those of then.
function Dashboard({ sheet, user }: { sheet: string; user: string }) {
  const { data: family = [sheet] } = useFamily(sheet);
  const { data: role } = useUserRole(sheet, user);
  const [counts, setCounts] = useState<Map<string, Counts>>(new Map());
  const report = useCallback((s: string, c: Counts) => setCounts((prev) => new Map(prev).set(s, c)), []);
  const shown = family.map((s) => counts.get(s)).filter((c): c is Counts => c !== undefined);
  const total = (k: keyof Counts) => shown.reduce((n, c) => n + c[k], 0);
  const steward = role?.role === 'steward';

  return (
    <section>
      {family.map((s) => (
        <SheetCounts key={s} sheet={s} report={report} />
      ))}
      <h2>Dashboard</h2>
      <p>
        Pending: <strong data-testid="dash-pending-count">{steward ? total('pending') : ''}</strong>{' '}
        Review: <strong data-testid="dash-review-count">{steward ? total('review') : ''}</strong>{' '}
        Overdue: <strong data-testid="dash-overdue-count">{steward ? total('overdue') : ''}</strong>
      </p>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 29, Component: Dashboard });
